INSERT INTO diseases (name, poultry_types, symptoms, cause, treatment, prevention, mortality_rate, recommended_medicines) VALUES
('Newcastle Disease', ARRAY['broiler','layer','kienyeji'], ARRAY['twisted neck','laboured breathing','greenish diarrhoea','dull eyes','ruffled feathers','sudden death'], 'Avian paramyxovirus type 1', 'No specific treatment; supportive care: electrolytes, vitamins. Vaccination of remaining flock.', 'Vaccinate at 1 day, 21 days, 8 weeks. Biosecurity: isolate new birds, disinfect footwear.', 'High (80-100% in unvaccinated)', ARRAY['Newcastle vaccine (LaSota)','Electrolyte supplements','Multivitamins']),
('Gumboro Disease (IBD)', ARRAY['broiler','layer'], ARRAY['drooping wings','ruffled feathers','huddled posture','bloody/watery white droppings','lethargy','vent picking'], 'Infectious bursal disease virus', 'No antiviral. Supportive care: warm environment, electrolyte water. Antibiotics for secondary infections.', 'Vaccinate breeders and chicks. Strict hygiene between batches.', 'Moderate to high (20-50%)', ARRAY['Gumboro vaccine (intermediate)','Amoxycillin','Vitamin C']),
('Fowl Pox', ARRAY['broiler','layer','kienyeji'], ARRAY['dark raised scabby lesions on comb/wattles','nodules around eyes','difficulty eating','weight loss','drop in egg production'], 'Avian poxvirus', 'No treatment. Supportive: soft food, clean water. Apply iodine to lesions if severe.', 'Vaccination with fowl pox vaccine. Mosquito control (vector).', 'Low (1-5%) but causes production loss', ARRAY['Fowl pox vaccine','Iodine solution','Antiseptic spray']),
('Coccidiosis', ARRAY['broiler','layer','kienyeji'], ARRAY['bloody reddish-brown droppings','hunched posture','pale comb','ruffled feathers','weakness','poor growth'], 'Eimeria protozoa (multiple species)', 'Anticoccidial drugs in water. Supportive: vitamins A, D, K. Clean dry litter.', 'Use coccidiostats in feed. Keep litter dry. Rotate anticoccidials to prevent resistance.', 'Moderate (10-40% in severe cases)', ARRAY['Amprolium','Toltrazuril','Sulphonamides','Vitamin K']),
('Marek''s Disease', ARRAY['broiler','layer'], ARRAY['leg paralysis (one leg forward, one back)','grey eye (iris colour change)','tumours on skin/feather follicles','weight loss','sudden death'], 'Marek''s disease virus (herpesvirus)', 'No treatment. Cull affected birds. Vaccinate day-old chicks.', 'Vaccinate at hatchery. Genetic resistance. Biosecurity to reduce early exposure.', 'High (50-80% in unvaccinated)', ARRAY['Marek''s vaccine (HVT)','No direct medicines']),
('Fowl Typhoid', ARRAY['broiler','layer','kienyeji'], ARRAY['greenish-yellow diarrhoea','pale comb/wattles','depression','drooping wings','reduced feed intake'], 'Salmonella gallinarum', 'Antibiotics (oxytetracycline, enrofloxacin). Disinfect house. Cull carriers.', 'Rodent control. Buy Salmonella-free stock. Biosecurity boots/dedicated tools.', 'Moderate to high (20-60%)', ARRAY['Oxytetracycline','Enrofloxacin','Disinfectant']),
('Infectious Bronchitis (IB)', ARRAY['broiler','layer'], ARRAY['coughing','sneezing','watery eyes','misshapen eggs (wrinkled)','reduced egg production','nephritis (kidney damage)'], 'Coronavirus', 'No specific antiviral. Warm dry housing. Antibiotics for secondary bacterial infection.', 'Vaccination (multiple serotypes). All-in-all-out management.', 'Low (1-10%) but egg production drops 50%', ARRAY['IB vaccine (Massachusetts/Arkansas strains)','Tylosin','Electrolytes']),
('Infectious Coryza', ARRAY['broiler','layer','kienyeji'], ARRAY['facial swelling (eyes/wattles)','foul-smelling nasal discharge','watery eyes','laboured breathing','decreased feed/water'], 'Avibacterium paragallinarum', 'Sulphonamides, erythromycin, or oxytetracycline. Clean waterers. Isolate sick birds.', 'Biosecurity – avoid introduction of carriers. Vaccination available but not common in Kenya.', 'Low (1-5%) but morbidity 50%', ARRAY['Sulphadimethoxine','Erythromycin','Oxytetracycline']),
('Mycoplasmosis (CRD)', ARRAY['broiler','layer'], ARRAY['nasal discharge','coughing','sinus swelling','bubbly eyes','poor growth','reduced egg production'], 'Mycoplasma gallisepticum', 'Tylosin, enrofloxacin, or tetracyclines in water. Long recovery.', 'Buy Mycoplasma-free chicks. Biosecurity (vertical transmission common).', 'Low mortality but chronic production loss', ARRAY['Tylosin tartrate','Enrofloxacin','Doxycycline']),
('Avian Influenza (Low Path)', ARRAY['broiler','layer','kienyeji'], ARRAY['sudden drop in egg production','respiratory signs','swollen head','purplish comb','diarrhoea'], 'Influenza A virus (low pathogenic strains)', 'No treatment in Kenya (reportable disease). Quarantine, culling if severe.', 'Biosecurity – prevent contact with wild waterfowl. Surveillance.', 'Low to moderate (5-15%)', ARRAY['Notify vet immediately','No over-the-counter meds']),
('Pullorum Disease', ARRAY['broiler','layer','kienyeji'], ARRAY['white pasted vent','chicks huddling','chirping','difficulty breathing','dead in first 2 weeks'], 'Salmonella pullorum', 'No treatment (carriers). Cull entire flock if confirmed. Disinfect house.', 'Buy from Pullorum-clean sources. Blood test breeders. Biosecurity.', 'High (50-80% in chicks)', ARRAY['No treatment – culling required']),
('Egg Drop Syndrome (EDS)', ARRAY['layer'], ARRAY['thin-shelled/soft eggs','pale eggs','loss of shell colour','normal feed intake','no respiratory signs'], 'Adenovirus', 'No treatment. Vaccinate at 16-18 weeks with EDS vaccine. Supportive nutrition.', 'Vaccinate pullets before lay. Biosecurity (faecal-oral spread).', 'Low mortality, but 40% production loss', ARRAY['EDS vaccine','Calcium supplement','Vitamin D3']),
('Botulism', ARRAY['broiler','layer','kienyeji'], ARRAY['progressive paralysis','limp neck (limberneck)','closed eyelids','difficulty breathing','sudden death'], 'Clostridium botulinum toxin (from rotten feed/carcasses)', 'Remove toxin source. Epsom salts (laxative). Supportive: glucose water. Antitoxin rare.', 'Dispose of dead birds immediately. Clean feeders. No rotten vegetable matter.', 'High (50-80%)', ARRAY['Epsom salts','Electrolytes','Charcoal (adsorbent)']),
('Omphalitis (Mushy Chick)', ARRAY['broiler','layer'], ARRAY['swollen/yellowish navel','lethargy','rough feathers','huddling','high mortality first week'], 'Bacterial infection (E. coli, Staphylococcus) – poor hatchery hygiene', 'Antibiotics (amoxycillin, enrofloxacin) in water. Warm brooder. Cull severely affected.', 'Disinfect hatchery equipment. Collect eggs cleanly. Brooder hygiene.', 'High (30-80%)', ARRAY['Amoxycillin','Enrofloxacin','Chlorhexidine disinfectant']),
('Aspergillosis', ARRAY['broiler','layer','kienyeji'], ARRAY['gasping','rapid breathing','yellowish nodules in mouth','eye swelling (fungal plaque)','emaciation'], 'Aspergillus fumigatus (mouldy litter/feed)', 'Remove mouldy litter. Nystatin or itraconazole (rarely used). Supportive care.', 'Dry clean litter. Avoid mouldy feed. Ventilation.', 'Moderate (10-30%)', ARRAY['Nystatin','Copper sulphate (low conc.)','Vitamin A']),
('Necrotic Enteritis', ARRAY['broiler'], ARRAY['sudden spike in mortality','bloody dark droppings','hunched birds','ruffled feathers','diarrhoea'], 'Clostridium perfringens (often after coccidiosis)', 'Amoxycillin, penicillin, or bacitracin in water. Treat coccidiosis first.', 'Prevent coccidiosis. Avoid high-protein/ fishmeal diets. Clean litter.', 'Moderate to high (20-50%)', ARRAY['Amoxycillin','Bacitracin methylene disalicylate','Probiotics']),
('Vitamin A Deficiency', ARRAY['broiler','layer','kienyeji'], ARRAY['white plaques in mouth/throat','crusty eyes','ruffled feathers','poor growth','watery eye discharge'], 'Poor quality feed, lack of green vegetables or vitamin premix', 'Vitamin A supplement (10,000 IU/kg feed for 1 week). Add green leafy vegetables.', 'Use commercial feed with balanced vitamins. Offer fresh greens.', 'Low mortality but stunted growth', ARRAY['Vitamin A oral drops','Multivitamin premix','Carrots/greens']),
('Cannibalism (Behavioural)', ARRAY['broiler','layer','kienyeji'], ARRAY['pecking vents/feathers/toes','bloodied birds','feather loss','stress','high mortality from bleeding'], 'Overcrowding, bright light, protein deficiency, boredom', 'Reduce light intensity. Provide pecking blocks. Increase dietary methionine. Beak trimming (last resort).', 'Proper stocking density (max 8-10 birds/m²). Balanced diet (methionine). Environmental enrichment.', 'Variable (5-30% if severe)', ARRAY['Methionine supplement','Red lights','Anti-pecking spray']),
('Heat Stress', ARRAY['broiler','layer','kienyeji'], ARRAY['panting','wings spread','lethargy','red comb','sudden death (midday)','reduced feed intake'], 'High ambient temperature (>32°C), poor ventilation, no shade/water', 'Move birds to shade. Provide cool water (add electrolytes/vitamin C). Mist fans. Reduce stocking density.', 'Plant trees. Install ventilation. Ensure water always available (nipple drinkers). Feed early morning/evening.', 'Moderate (5-20% during heatwave)', ARRAY['Vitamin C','Electrolyte powder','Potassium chloride']),
('Newcastle Disease (Variant)', ARRAY['broiler','layer','kienyeji'], ARRAY['mild respiratory signs','drop in egg production','few neurological signs','mild diarrhoea','moderate mortality'], 'Avian paramyxovirus (lentogenic or mesogenic strain)', 'Same as classic ND. Supportive care. Vaccination with appropriate strain.', 'Vaccination. Biosecurity.', 'Low (5-20%) but production loss high', ARRAY['Newcastle vaccine (VG/GA or Komarov)','Multivitamins']);
